<script setup>
import { ref, computed } from 'vue';
import OperatorPerusahaanLayout from '@/Layouts/OperatorPerusahaanLayout.vue';
import { Head, Link } from '@inertiajs/vue3';

defineOptions({ layout: OperatorPerusahaanLayout });

const configs = ref([
  { id: 1, key: 'company.nama', type: 'teks', value: 'PT Net Sejahtera', created_at: '2025-01-01' },
  { id: 2, key: 'company.alamat', type: 'teks', value: 'Jl. Merdeka No. 10, Jakarta Selatan', created_at: '2025-01-01' },
  { id: 3, key: 'company.logo', type: 'file', value: 'logo_netsejahtera.png', created_at: '2025-01-05' },
  { id: 4, key: 'company.billing_day', type: 'teks', value: '10', created_at: '2025-01-10' },
  { id: 5, key: 'invoice.prefix', type: 'teks', value: 'INV-NS', created_at: '2025-02-01' },
  { id: 6, key: 'invoice.template', type: 'file', value: 'template_invoice.html', created_at: '2025-02-01' },
  { id: 7, key: 'invoice.denda', type: 'teks', value: '5000', created_at: '2025-02-01' },
  { id: 8, key: 'wa.gateway_url', type: 'teks', value: 'https://api.whatsapp.com/send', created_at: '2025-03-01' },
    { id: 9, key: 'wa.api_key', type: 'teks', value: '[tersembunyi]', created_at: '2025-04-01' },
  { id: 10, key: 'invoice.denda_per_hari', type: 'teks', value: '2000', created_at: '2025-04-15' },
]);

const searchInput = ref(''); const search = ref(''); const typeFilter = ref(''); const currentPage = ref(1); const perPage = ref(10); const perPageOptions = [5, 10, 25, 50, 100];
const selectedIds = ref([]); const selectAll = ref(false); const sortFields = ref([]); const selectedItem = ref(null);
const showCreateModal = ref(false); const showDetailModal = ref(false); const showEditModal = ref(false); const showDeleteModal = ref(false);
const form = ref({ id: null, key: '', type: 'teks', value: '' }); const formErrors = ref({}); const nextId = ref(11);

function applySearch() { search.value = searchInput.value; currentPage.value = 1; } function clearSearch() { searchInput.value = ''; search.value = ''; currentPage.value = 1; }
function applyTypeFilter(t) { typeFilter.value = t; currentPage.value = 1; } function changePerPage(n) { perPage.value = n; currentPage.value = 1; }
function toggleSelectAll() { selectedIds.value = selectAll.value ? paginatedConfigs.value.map(c => c.id) : []; }
function toggleSelect(id) { const i = selectedIds.value.indexOf(id); i === -1 ? selectedIds.value.push(id) : selectedIds.value.splice(i, 1); selectAll.value = selectedIds.value.length === paginatedConfigs.value.length; }
function bulkDelete() { configs.value = configs.value.filter(c => !selectedIds.value.includes(c.id)); selectedIds.value = []; selectAll.value = false; }
function sort(field) { const e = sortFields.value.findIndex(s => s.field === field); if (e !== -1) { if (sortFields.value[e].dir === 'asc') sortFields.value[e].dir = 'desc'; else sortFields.value.splice(e, 1); } else sortFields.value.push({ field, dir: 'asc' }); }
function sortIcon(f) { const s = sortFields.value.find(s => s.field === f); if (!s) return 'fa-sort'; return s.dir === 'asc' ? 'fa-sort-up' : 'fa-sort-down'; } function sortOrder(f) { const i = sortFields.value.findIndex(s => s.field === f); return i !== -1 ? i + 1 : null; }
function typeBadge(t) { return t === 'file' ? 'bg-violet-100 text-violet-700 dark:bg-violet-900/30 dark:text-violet-400' : 'bg-sky-100 text-sky-700 dark:bg-sky-900/30 dark:text-sky-400'; }

const filteredConfigs = computed(() => {
  let r = [...configs.value]; if (search.value) { const q = search.value.toLowerCase(); r = r.filter(x => x.key.toLowerCase().includes(q) || x.value.toLowerCase().includes(q)); }
  if (typeFilter.value) r = r.filter(x => x.type === typeFilter.value); if (sortFields.value.length > 0) r.sort((a, b) => { for (const s of sortFields.value) { const av = a[s.field], bv = b[s.field]; if (av != bv) return (typeof av === 'string' ? av.localeCompare(bv) : av - bv) * (s.dir === 'asc' ? 1 : -1); } return 0; }); return r;
});
const totalPages = computed(() => Math.ceil(filteredConfigs.value.length / perPage.value) || 1); const paginatedConfigs = computed(() => { const s = (currentPage.value - 1) * perPage.value; return filteredConfigs.value.slice(s, s + perPage.value); });
const visiblePages = computed(() => { const p = []; const t = totalPages.value; const c = currentPage.value; let st = Math.max(1, c - 2); let en = Math.min(t, c + 2); if (en - st < 4) { if (st === 1) en = Math.min(t, st + 4); else st = Math.max(1, en - 4); } for (let i = st; i <= en; i++) p.push(i); return p; });

function openCreate() { form.value = { id: null, key: '', type: 'teks', value: '' }; formErrors.value = {}; showCreateModal.value = true; }
function openDetail(c) { selectedItem.value = c; showDetailModal.value = true; } function openEdit(c) { form.value = { ...c }; formErrors.value = {}; showEditModal.value = true; } function openDelete(c) { selectedItem.value = c; showDeleteModal.value = true; }
function validateForm() { const e = {}; if (!form.value.key.trim()) e.key = 'Key wajib diisi'; if (!form.value.value.trim()) e.value = 'Value wajib diisi'; formErrors.value = e; return Object.keys(e).length === 0; }
function saveCreate() { if (!validateForm()) return; configs.value.unshift({ id: nextId.value++, ...form.value, created_at: new Date().toISOString().split('T')[0] }); showCreateModal.value = false; }
function saveEdit() { if (!validateForm()) return; const i = configs.value.findIndex(c => c.id === form.value.id); if (i !== -1) configs.value[i] = { ...configs.value[i], ...form.value }; showEditModal.value = false; }
function confirmDelete() { configs.value = configs.value.filter(c => c.id !== selectedItem.value.id); showDeleteModal.value = false; if (paginatedConfigs.value.length === 0 && currentPage.value > 1) currentPage.value--; } function goToPage(p) { currentPage.value = Math.max(1, Math.min(p, totalPages.value)); }
</script>

